public:
    long long maxProduct(string s) {
        int n = s.size();
        vector<int> span(n, 0);
        int l = 0, r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 1 : min(span[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) k++;
            span[i] = k;
            k--;
            if (i + k > r) {
                l = i - k;
                r = i + k;
            }
        }
        vector<long long> left(n, 1), right(n, 1);
        for (int i = 0; i < n; i++) {
            left[i + span[i] - 1] = max(left[i + span[i] - 1], (long long)(2 * span[i] - 1));
            right[i - span[i] + 1] = max(right[i - span[i] + 1], (long long)(2 * span[i] - 1));
        }
        for (int i = n - 2; i >= 0; i--) left[i] = max(left[i], left[i + 1] - 2);
        for (int i = 1; i < n; i++) left[i] = max(left[i], left[i - 1]);
        for (int i = 1; i < n; i++) right[i] = max(right[i], right[i - 1] - 2);
        for (int i = n - 2; i >= 0; i--) right[i] = max(right[i], right[i + 1]);

        long long ans = 0;
        for (int i = 0; i < n - 1; i++) {
            ans = max(ans, left[i] * right[i + 1]);
        }
        return ans;
    }
};

class Solution {
    public long maxProduct(String s) {
        int n = s.length();
        int[] span = new int[n];
        int l = 0, r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 1 : Math.min(span[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s.charAt(i - k) == s.charAt(i + k)) k++;
            span[i] = k;
            k--;
            if (i + k > r) {
                l = i - k;
                r = i + k;
            }
        }
        long[] left = new long[n];
        long[] right = new long[n];
        java.util.Arrays.fill(left, 1);
        java.util.Arrays.fill(right, 1);
        for (int i = 0; i < n; i++) {
            left[i + span[i] - 1] = Math.max(left[i + span[i] - 1], 2 * span[i] - 1);
            right[i - span[i] + 1] = Math.max(right[i - span[i] + 1], 2 * span[i] - 1);
        }
        for (int i = n - 2; i >= 0; i--) left[i] = Math.max(left[i], left[i + 1] - 2);
        for (int i = 1; i < n; i++) left[i] = Math.max(left[i], left[i - 1]);
        for (int i = 1; i < n; i++) right[i] = Math.max(right[i], right[i - 1] - 2);
        for (int i = n - 2; i >= 0; i--) right[i] = Math.max(right[i], right[i + 1]);

        long ans = 0;
        for (int i = 0; i < n - 1; i++) {
            ans = Math.max(ans, left[i] * right[i + 1]);
        }
        return ans;
    }
}

